import { useMemo } from "react";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { AreaChart, Area, BarChart, Bar, PieChart, Pie, Cell, XAxis, YAxis, Tooltip, ResponsiveContainer, Legend } from "recharts";

type ThreatItem = {
  severity: string;
  category: string;
  published_at: string;
  source_name: string;
};

const SEV_COLORS: Record<string, string> = {
  critical: "hsl(0 84% 60%)",
  high: "hsl(38 92% 50%)",
  medium: "hsl(174 84% 52%)",
  low: "hsl(142 76% 45%)",
};

const CAT_PALETTE = [
  "hsl(174 84% 52%)", "hsl(280 70% 60%)", "hsl(38 92% 50%)", "hsl(0 84% 60%)",
  "hsl(200 80% 55%)", "hsl(120 60% 50%)", "hsl(30 90% 55%)", "hsl(250 70% 65%)",
];

function CustomTooltip({ active, payload, label }: any) {
  if (!active || !payload?.length) return null;
  return (
    <div className="rounded-lg border border-border/60 bg-card/95 px-3 py-2 text-xs shadow-lg backdrop-blur">
      {label && <div className="text-muted-foreground mb-1">{label}</div>}
      {payload.map((p: any) => (
        <div key={p.dataKey || p.name} className="flex items-center gap-2">
          <span className="h-2 w-2 rounded-full" style={{ background: p.color }} />
          <span className="text-foreground">{p.name || p.dataKey}: <strong>{p.value}</strong></span>
        </div>
      ))}
    </div>
  );
}

export function SeverityDonut({ items }: { items: ThreatItem[] }) {
  const data = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const item of items) counts[item.severity] = (counts[item.severity] || 0) + 1;
    return Object.entries(counts)
      .sort(([a], [b]) => ["critical","high","medium","low"].indexOf(a) - ["critical","high","medium","low"].indexOf(b))
      .map(([name, value]) => ({ name: name.toUpperCase(), value }));
  }, [items]);

  if (!data.length) return null;

  return (
    <Card className="border-border/60 bg-card/60 backdrop-blur">
      <CardHeader className="pb-2">
        <CardTitle className="text-sm">Severity Distribution</CardTitle>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={200}>
          <PieChart>
            <Pie data={data} cx="50%" cy="50%" innerRadius={50} outerRadius={80} paddingAngle={3} dataKey="value">
              {data.map((entry) => (
                <Cell key={entry.name} fill={SEV_COLORS[entry.name.toLowerCase()] || "#888"} />
              ))}
            </Pie>
            <Tooltip content={<CustomTooltip />} />
            <Legend iconType="circle" iconSize={8} wrapperStyle={{ fontSize: "11px" }} />
          </PieChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}

export function CategoryBar({ items }: { items: ThreatItem[] }) {
  const data = useMemo(() => {
    const counts: Record<string, number> = {};
    for (const item of items) counts[item.category] = (counts[item.category] || 0) + 1;
    return Object.entries(counts)
      .sort((a, b) => b[1] - a[1])
      .slice(0, 10)
      .map(([name, value]) => ({ name: name.length > 16 ? name.slice(0, 14) + "…" : name, value }));
  }, [items]);

  if (!data.length) return null;

  return (
    <Card className="border-border/60 bg-card/60 backdrop-blur">
      <CardHeader className="pb-2">
        <CardTitle className="text-sm">Top Categories</CardTitle>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={200}>
          <BarChart data={data} layout="vertical" margin={{ left: 0, right: 8 }}>
            <XAxis type="number" hide />
            <YAxis type="category" dataKey="name" width={100} tick={{ fontSize: 10, fill: "hsl(215 20% 65%)" }} />
            <Tooltip content={<CustomTooltip />} />
            <Bar dataKey="value" radius={[0, 4, 4, 0]}>
              {data.map((_, i) => (
                <Cell key={i} fill={CAT_PALETTE[i % CAT_PALETTE.length]} />
              ))}
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}

export function VolumeArea({ items }: { items: ThreatItem[] }) {
  const data = useMemo(() => {
    const hourMap = new Map<string, { total: number; critical: number; high: number }>();
    const now = Date.now();
    for (let h = 23; h >= 0; h--) {
      const d = new Date(now - h * 3600000);
      const key = `${String(d.getHours()).padStart(2, "0")}:00`;
      hourMap.set(key, { total: 0, critical: 0, high: 0 });
    }
    for (const item of items) {
      const d = new Date(item.published_at);
      if (now - d.getTime() > 24 * 3600000) continue;
      const key = `${String(d.getHours()).padStart(2, "0")}:00`;
      const entry = hourMap.get(key);
      if (entry) {
        entry.total++;
        if (item.severity === "critical") entry.critical++;
        if (item.severity === "high") entry.high++;
      }
    }
    return [...hourMap.entries()].map(([hour, v]) => ({ hour, ...v }));
  }, [items]);

  return (
    <Card className="border-border/60 bg-card/60 backdrop-blur col-span-2">
      <CardHeader className="pb-2">
        <CardTitle className="text-sm">Threat Volume — Last 24 Hours</CardTitle>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={160}>
          <AreaChart data={data} margin={{ top: 4, right: 4, left: -30, bottom: 0 }}>
            <defs>
              <linearGradient id="gradTotal" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="hsl(174 84% 52%)" stopOpacity={0.3} />
                <stop offset="95%" stopColor="hsl(174 84% 52%)" stopOpacity={0} />
              </linearGradient>
              <linearGradient id="gradCrit" x1="0" y1="0" x2="0" y2="1">
                <stop offset="5%" stopColor="hsl(0 84% 60%)" stopOpacity={0.4} />
                <stop offset="95%" stopColor="hsl(0 84% 60%)" stopOpacity={0} />
              </linearGradient>
            </defs>
            <XAxis dataKey="hour" tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} interval={3} />
            <YAxis tick={{ fontSize: 9, fill: "hsl(215 20% 65%)" }} />
            <Tooltip content={<CustomTooltip />} />
            <Area type="monotone" dataKey="total" stroke="hsl(174 84% 52%)" fill="url(#gradTotal)" strokeWidth={1.5} name="Total" />
            <Area type="monotone" dataKey="critical" stroke="hsl(0 84% 60%)" fill="url(#gradCrit)" strokeWidth={1.5} name="Critical" />
          </AreaChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}

export function SourceHealthGrid({ sources }: { sources: Array<{ name: string; last_status: string | null; last_fetched_at: string | null; category: string }> }) {
  if (!sources.length) return null;

  const getStatus = (s: { last_status: string | null }) => {
    if (!s.last_status) return { label: "Never", color: "text-muted-foreground" };
    if (s.last_status.startsWith("ok")) return { label: "OK", color: "text-success" };
    if (s.last_status.startsWith("err")) return { label: "ERR", color: "text-destructive" };
    return { label: s.last_status.slice(0, 4), color: "text-warning" };
  };

  const okCount = sources.filter(s => s.last_status?.startsWith("ok")).length;
  const errCount = sources.filter(s => s.last_status?.startsWith("err")).length;
  const neverCount = sources.filter(s => !s.last_status).length;

  return (
    <Card className="border-border/60 bg-card/60 backdrop-blur">
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm">Source Health</CardTitle>
          <div className="flex gap-3 text-[10px]">
            <span className="text-success">✓ {okCount}</span>
            <span className="text-destructive">✗ {errCount}</span>
            <span className="text-muted-foreground">○ {neverCount}</span>
          </div>
        </div>
      </CardHeader>
      <CardContent>
        <div className="grid grid-cols-6 gap-1 md:grid-cols-8 lg:grid-cols-10">
          {sources.map(s => {
            const st = getStatus(s);
            return (
              <div
                key={s.name}
                title={`${s.name}\n${s.last_status || "Never fetched"}`}
                className={`h-2 w-full rounded-sm cursor-pointer transition-opacity hover:opacity-70 ${
                  st.label === "OK" ? "bg-success/70" : st.label === "ERR" ? "bg-destructive/70" : "bg-muted/50"
                }`}
              />
            );
          })}
        </div>
        <p className="text-[10px] text-muted-foreground mt-2">Each block = 1 source. Hover for details.</p>
      </CardContent>
    </Card>
  );
}
