import { useEffect, useState, useCallback } from "react";
import { supabase } from "@/integrations/supabase/client";

interface OrgProfile {
  tech_keywords: string[];
  company_domains: string[];
  internal_ips: string[];
  industry: string;
  min_confidence: number;
  alert_threshold: string;
}

interface ThreatItem {
  id: string;
  title: string;
  excerpt?: string | null;
  severity: string;
  iocs?: { cves?: string[]; ipv4?: string[]; domains?: string[]; sha256?: string[] } | null;
  confidence_score?: number;
  source_name?: string;
}

const SEVERITY_RANK: Record<string, number> = { critical: 4, high: 3, medium: 2, low: 1 };
const THRESHOLD_RANK: Record<string, number> = { critical: 4, high: 3, medium: 2, low: 1 };

const INDUSTRY_KEYWORDS: Record<string, string[]> = {
  "Finance / Banking":   ["bank","financial","payment","swift","atm","wire transfer","fraud","card","fintech","cryptocurrency"],
  "Healthcare":          ["hospital","patient","ehr","health","medical","hipaa","clinical","pharmacy","fda"],
  "Government":          ["government","federal","agency","military","national security","defense","critical infrastructure"],
  "Energy / Utilities":  ["power grid","scada","ics","ot","industrial","energy","utility","pipeline","nuclear"],
  "Technology":          ["saas","cloud","api","devops","kubernetes","docker","github","ci/cd","software"],
  "Retail / E-Commerce": ["ecommerce","pos","magecart","skimming","shopping cart","payment gateway","card data"],
  "Education":           ["university","student data","canvas","moodle","academic","school"],
  "Telecom":             ["telecom","carrier","ss7","voip","5g","sim swap"],
};

export function useRelevanceFilter() {
  const [profile, setProfile] = useState<OrgProfile | null>(null);
  const [enabled, setEnabled] = useState(false);

  useEffect(() => {
    supabase.from("org_settings").select("*").limit(1).then(({ data }) => {
      if (data && data.length > 0) {
        setProfile({
          tech_keywords:    data[0].tech_keywords ?? [],
          company_domains:  data[0].company_domains ?? [],
          internal_ips:     data[0].internal_ips ?? [],
          industry:         data[0].industry ?? "Technology",
          min_confidence:   data[0].min_confidence ?? 0,
          alert_threshold:  data[0].alert_threshold ?? "low",
        });
      }
    });
  }, []);

  const scoreRelevance = useCallback((item: ThreatItem): number => {
    if (!profile) return 50;
    let score = 0;
    const text = `${item.title} ${item.excerpt ?? ""}`.toLowerCase();

    // Tech stack keyword match
    for (const kw of profile.tech_keywords) {
      if (text.includes(kw.toLowerCase())) score += 20;
    }

    // Industry keyword match
    const industryKws = INDUSTRY_KEYWORDS[profile.industry] ?? [];
    for (const kw of industryKws) {
      if (text.includes(kw)) score += 15;
    }

    // Company domain IOC match
    for (const domain of profile.company_domains) {
      if ((item.iocs?.domains ?? []).some(d => d.includes(domain) || domain.includes(d))) score += 30;
    }

    // Internal IP IOC match
    for (const ip of profile.internal_ips) {
      const baseIp = ip.split("/")[0];
      if ((item.iocs?.ipv4 ?? []).some(i => i.startsWith(baseIp.split(".").slice(0, 2).join(".")))) score += 25;
    }

    return Math.min(score, 100);
  }, [profile]);

  const isRelevant = useCallback((item: ThreatItem): boolean => {
    if (!profile || !enabled) return true;

    // Confidence filter
    if (profile.min_confidence > 0 && (item.confidence_score ?? 50) < profile.min_confidence) return false;

    // Severity threshold
    const sevRank = SEVERITY_RANK[item.severity] ?? 0;
    const threshRank = THRESHOLD_RANK[profile.alert_threshold] ?? 0;
    if (sevRank < threshRank) return false;

    return true;
  }, [profile, enabled]);

  const filterRelevant = useCallback(<T extends ThreatItem>(items: T[]): T[] => {
    if (!enabled) return items;
    return items.filter(isRelevant);
  }, [enabled, isRelevant]);

  return {
    profile,
    enabled,
    setEnabled,
    scoreRelevance,
    isRelevant,
    filterRelevant,
    hasProfile: !!(profile?.tech_keywords.length || profile?.company_domains.length),
  };
}
