// ── Helpers ───────────────────────────────────────────────────────────────────
function timeAgo(iso: string): string {
  const diff = Date.now() - new Date(iso).getTime();
  const m = Math.floor(diff / 60000);
  if (m < 1) return "just now";
  if (m < 60) return `${m}m ago`;
  const h = Math.floor(m / 60);
  if (h < 24) return `${h}h ago`;
  return `${Math.floor(h / 24)}d ago`;
}

// ── Export helpers ────────────────────────────────────────────────────────────
function exportCSV(items: ThreatItem[]) {
  const header = ["id","title","severity","category","source_name","published_at","link","cves","ips","sha256","excerpt"];
  const rows = items.map(i => [
    i.id, `"${(i.title||"").replace(/"/g,'""')}"`, i.severity, i.category,
    i.source_name, i.published_at, i.link,
    (i.iocs?.cves||[]).join("|"), (i.iocs?.ipv4||[]).join("|"), (i.iocs?.sha256||[]).join("|"),
    `"${(i.excerpt||"").replace(/"/g,'""').slice(0,200)}"`,
  ].join(","));
  const blob = new Blob([[header.join(","), ...rows].join("\n")], { type: "text/csv" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `threatlens-${new Date().toISOString().slice(0,10)}.csv`;
  a.click();
  URL.revokeObjectURL(a.href);
}
function exportJSON(items: ThreatItem[]) {
  const blob = new Blob([JSON.stringify(items, null, 2)], { type: "application/json" });
  const a = document.createElement("a");
  a.href = URL.createObjectURL(blob);
  a.download = `threatlens-${new Date().toISOString().slice(0,10)}.json`;
  a.click();
  URL.revokeObjectURL(a.href);
}

// ── CopyableIOC badge ─────────────────────────────────────────────────────────
function CopyableIOC({ value, href, className }: { value: string; href?: string; className?: string }) {
  const [copied, setCopied] = useState(false);
  const copy = useCallback((e: React.MouseEvent) => {
    e.preventDefault(); e.stopPropagation();
    navigator.clipboard.writeText(value).then(() => { setCopied(true); setTimeout(() => setCopied(false), 1500); });
  }, [value]);
  const badge = (
    <Badge variant="outline"
      className={`font-mono text-[10px] cursor-pointer hover:border-primary/60 transition-colors ${className || ""}`}
      onClick={copy}>
      {copied ? <Check className="h-2.5 w-2.5 text-success mr-1" /> : null}{value}
    </Badge>
  );
  return (
    <span className="inline-flex items-center gap-0.5">
      {href ? <a href={href} target="_blank" rel="noopener noreferrer" onClick={e => e.stopPropagation()}>{badge}</a> : badge}
      <button onClick={copy} className="text-muted-foreground hover:text-primary transition-colors" title="Copy">
        {copied ? <Check className="h-2.5 w-2.5 text-success" /> : <Copy className="h-2.5 w-2.5" />}
      </button>
    </span>
  );
}

