const BRIEF_HEADERS = [
  // ai-brief edge function format (Google + Groq grounded)
  "THREAT BRIEF","WHAT HAPPENED","WHO IS AFFECTED","EXPLOITATION STATUS",
  "INDICATORS OF COMPROMISE","RECOMMENDED ACTIONS","RELATED INTEL (Internal DB)",
  "RELATED COVERAGE (Google News Live)","SOURCES",
  // New enterprise CTI format
  "EXECUTIVE OVERVIEW","KEY INTELLIGENCE ASSESSMENT","THREAT LANDSCAPE CONTEXT",
  "INDICATORS & EARLY WARNING SIGNALS","RECOMMENDED MITIGATIONS","INTELLIGENCE GAPS","ANALYST CONCLUSION",
  // Legacy / offline brief formats
  "EXECUTIVE SUMMARY","KEY THREAT HIGHLIGHTS","ATTACK FLOW",
  "TACTICS, TECHNIQUES & PROCEDURES (MITRE ATT&CK)","INDICATORS OF COMPROMISE",
  "IMPACT ASSESSMENT","RECOMMENDATIONS / MITIGATION","TRENDS & INSIGHTS",
  "THREAT ACTOR","WHAT HAPPENED","ATTACK CHAIN","HOW YOU GET COMPROMISED",
  "IMMEDIATE ACTIONS REQUIRED","ANALYST NOTE",
];

type BriefSource = { title: string; link: string; snippet: string; source: string; published_at?: string };
type BriefRelated = { title: string; source_name: string; severity?: string; excerpt?: string };

function normalizeBriefForDisplay(text: string): string {
  const headers = [
    "THREAT BRIEF", "WHAT HAPPENED", "WHO IS AFFECTED", "EXPLOITATION STATUS",
    "INDICATORS OF COMPROMISE", "RECOMMENDED ACTIONS", "RELATED INTEL (Internal DB)",
    "RELATED COVERAGE (Google News Live)", "SOURCES",
  ];
  let out = text.replace(/\r\n/g, "\n");
  for (const h of headers) {
    out = out.replace(new RegExp(`\\*\\*${h.replace(/[()]/g, "\\$&")}\\*\\*`, "gi"), `\n\n${h}\n`);
  }
  return out.replace(/\*\*([^*\n]+)\*\*/g, "$1").replace(/\n{3,}/g, "\n\n").trim();
}

async function fetchGroundedBrief(itemId: string): Promise<{ brief: string; sources: BriefSource[]; related: BriefRelated[]; model: string } | null> {
  const { data, error } = await supabase.functions.invoke("ai-brief", {
    body: { ids: [itemId], force: true },
  });
  if (error) throw new Error(error.message);
  const result = (data as any)?.results?.[0];
  if (result?.brief) {
    return {
      brief: normalizeBriefForDisplay(result.brief),
      sources: result.sources || [],
      related: result.related || [],
      model: result.model || "ai-brief",
    };
  }
  const { data: row } = await supabase
    .from("threat_items")
    .select("ai_summary,ai_summary_model")
    .eq("id", itemId)
    .single();
  if (row?.ai_summary) {
    return { brief: normalizeBriefForDisplay(row.ai_summary), sources: [], related: [], model: row.ai_summary_model || "stored" };
  }
  return null;
}
function parseBrief(text: string): { title: string; body: string }[] {
  const found: { header: string; pos: number }[] = [];
  for (const h of BRIEF_HEADERS) { const idx = text.indexOf(h); if (idx !== -1) found.push({ header: h, pos: idx }); }
  found.sort((a, b) => a.pos - b.pos);
  return found.map(({ header, pos }, i) => {
    const body = text.slice(pos + header.length, found[i+1]?.pos ?? pos + header.length + 2000).trim();
    return { title: header, body };
  }).filter(s => s.body);
}
function parseBriefFast(text: string): Record<string, string> {
  const found: { key: string; pos: number }[] = [];
  for (const h of BRIEF_HEADERS) { const idx = text.indexOf(h); if (idx !== -1) found.push({ key: h, pos: idx }); }
  found.sort((a, b) => a.pos - b.pos);
  const r: Record<string, string> = {};
  for (let i = 0; i < found.length; i++) {
    const { key, pos } = found[i];
    const body = text.slice(pos + key.length, found[i+1]?.pos ?? pos + key.length + 1500).replace(/^[::\s]+/,"").trim();
    if (body) r[key] = body;
  }
  return r;
}

