// ── Today's Auto AI Brief ─────────────────────────────────────────────────────
function AITodayBrief({ items }: { items: ThreatItem[] }) {
  const [briefs, setBriefs]     = useState<Record<string, string>>({});
  const [loading, setLoading]   = useState<Set<string>>(new Set());
  const [expanded, setExpanded] = useState<string | null>(null);
  const generated = useRef(new Set<string>());

  useEffect(() => {
    const top = items.filter(i => i.severity==="critical"||i.severity==="high"||isPriority(i.source_name)).slice(0,3);
    if (!top.length) return;
    const pending = top.filter(item => !generated.current.has(item.id));
    if (!pending.length) return;
    pending.forEach(item => generated.current.add(item.id));
    setLoading(new Set(pending.map(i => i.id)));

    (async () => {
      try {
        const { data, error } = await supabase.functions.invoke("ai-brief", {
          body: { ids: pending.map(i => i.id), force: true },
        });
        if (!error && (data as any)?.results?.length) {
          const next: Record<string, string> = {};
          for (const r of (data as any).results) {
            if (r.id && r.brief) {
              next[r.id] = r.brief;
              _briefCache.set(r.id, r.brief);
            }
          }
          setBriefs(prev => ({ ...prev, ...next }));
        } else {
          await Promise.all(pending.map(async item => {
            const grounded = await fetchGroundedBrief(item.id).catch(() => null);
            const brief = grounded?.brief || await generateAIBrief(item);
            _briefCache.set(item.id, brief);
            setBriefs(prev => ({ ...prev, [item.id]: brief }));
          }));
        }
      } catch {
        await Promise.all(pending.map(async item => {
          const brief = await generateAIBrief(item);
          _briefCache.set(item.id, brief);
          setBriefs(prev => ({ ...prev, [item.id]: brief }));
        }));
      } finally {
        setLoading(new Set());
      }
    })();
  }, [items.length]);

  const top = items.filter(i => i.severity==="critical"||i.severity==="high"||isPriority(i.source_name)).slice(0,3);
  if (!top.length) return null;

  return (
    <div className="mb-6 rounded-xl border border-primary/20 bg-primary/[0.03] overflow-hidden">
      <div className="flex items-center justify-between px-5 py-3 border-b border-primary/15">
        <div className="flex items-center gap-2">
          <Sparkles className="h-4 w-4 text-primary" />
          <span className="text-sm font-bold">Today's AI Intelligence Brief</span>
          <span className="text-[10px] text-muted-foreground">· auto-generated · {top.length} threats</span>
        </div>
        <span className="text-[10px] text-muted-foreground">Google News + Groq · grounded</span>
      </div>
      <div className="divide-y divide-border/30">
        {top.map(item => {
          const sev = SEV[item.severity] || SEV.medium;
          const brief = briefs[item.id] || "";
          const isLoading = loading.has(item.id);
          const isOpen = expanded === item.id;
          const sections = brief ? parseBriefFast(brief) : {};
          return (
            <div key={item.id} className={`border-l-4 ${sev.border}`}>
              <button className="w-full text-left px-5 py-3 hover:bg-muted/20 transition-colors" onClick={() => setExpanded(isOpen ? null : item.id)}>
                <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                  <span className={`text-[10px] font-bold px-2 py-0.5 rounded ${sev.badge}`}>{sev.label}</span>
                  <span className={`text-[10px] font-medium ${isPriority(item.source_name)?"text-primary":"text-muted-foreground"}`}>{item.source_name}</span>
                  <span className="text-[10px] text-muted-foreground ml-auto flex items-center gap-1"><Clock className="h-3 w-3" />{timeAgo(itemDisplayDate(item))}</span>
                </div>
                <div className="text-sm font-semibold leading-snug">{item.title}</div>
                {isLoading && <div className="mt-2 flex items-center gap-2 text-[11px] text-muted-foreground"><RefreshCw className="h-3 w-3 animate-spin text-primary" />Racing AI models…</div>}
                {!isLoading && brief && !isOpen && (
                  <div className="mt-2 space-y-1">
                    {sections["THREAT ACTOR"] && <div className="text-[11px]"><span className="text-muted-foreground font-semibold">Actor: </span><span className="text-foreground/80">{sections["THREAT ACTOR"].slice(0,100)}</span></div>}
                    {sections["WHAT HAPPENED"] && <div className="text-[11px] text-muted-foreground line-clamp-2">{sections["WHAT HAPPENED"].slice(0,180)}</div>}
                    <div className="text-[10px] text-primary mt-1">Click to see attack chain + IOCs + remediation ↓</div>
                  </div>
                )}
              </button>
              {isOpen && brief && (
                <div className="border-t border-border/30 bg-background/50">
                  {Object.entries(sections).map(([title, body]) => (
                    <div key={title} className={`px-5 py-3 border-b border-border/20 ${title==="ATTACK CHAIN"?"bg-orange-400/5":title==="HOW YOU GET COMPROMISED"?"bg-red-500/5":""}`}>
                      <div className={`text-[10px] font-bold uppercase tracking-widest mb-1.5 ${title==="ATTACK CHAIN"?"text-orange-400":title==="HOW YOU GET COMPROMISED"?"text-red-400":title==="IMMEDIATE ACTIONS REQUIRED"?"text-green-400":"text-muted-foreground"}`}>
                        {title==="ATTACK CHAIN"?"⛓ ":title==="HOW YOU GET COMPROMISED"?"⚠️ ":title==="IMMEDIATE ACTIONS REQUIRED"?"🚨 ":""}{title}
                      </div>
                      <div className="text-sm text-foreground/90 leading-relaxed whitespace-pre-wrap">{body}</div>
                    </div>
                  ))}
                  <div className="px-5 py-2.5">
                    <a href={item.link} target="_blank" rel="noopener noreferrer" className="text-xs font-medium text-primary hover:underline flex items-center gap-1">
                      Read full article <ExternalLink className="h-3 w-3" />
                    </a>
                  </div>
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ── Notification Bar ──────────────────────────────────────────────────────────
function NotificationBar({ failing }: { failing: { name: string; error: string }[] }) {
  const [open, setOpen] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  if (!failing.length || dismissed) return null;
  const fixFor = (e: string) => {
    if (e.includes("404")||e.includes("not found")) return "Feed URL has moved. Update in Settings.";
    if (e.includes("403")||e.includes("401")) return "Source requires auth. Consider disabling.";
    if (e.includes("timeout")||e.includes("abort")) return "Source is slow — retries automatically.";
    return "Network issue — retries on next cycle.";
  };
  return (
    <div className="mb-4 rounded-lg border border-orange-400/30 bg-orange-400/5 text-sm">
      <div className="flex items-center justify-between px-4 py-2.5">
        <div className="flex items-center gap-2">
          <AlertTriangle className="h-3.5 w-3.5 text-orange-400 shrink-0" />
          <span className="font-medium text-orange-400">{failing.length} source{failing.length>1?"s":""} failing</span>
          <span className="text-xs text-muted-foreground">— retrying automatically every 15 min</span>
        </div>
        <div className="flex gap-2">
          <button onClick={() => setOpen(v => !v)} className="text-xs text-orange-400 hover:underline">{open?"Hide":"Show details"}</button>
          <button onClick={() => setDismissed(true)}><X className="h-3.5 w-3.5 text-muted-foreground" /></button>
        </div>
      </div>
      {open && (
        <div className="border-t border-orange-400/20 divide-y divide-border/30">
          {failing.map((f, i) => (
            <div key={i} className="px-4 py-2">
              <span className="font-medium">{f.name}</span>
              <div className="text-xs text-muted-foreground font-mono mt-0.5 truncate">{f.error.slice(0,80)}</div>
              <div className="text-xs mt-0.5"><span className="text-green-500 font-medium">Fix: </span>{fixFor(f.error)}</div>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

// ── Dashboard Live Search ─────────────────────────────────────────────────────
function DashboardSearch({ items }: { items: ThreatItem[] }) {
  const [q, setQ]               = useState("");
  const [webResults, setWebResults] = useState<any[]>([]);
  const [webLoading, setWebLoading] = useState(false);
  const [open, setOpen]         = useState(false);
  const debounce = useRef<ReturnType<typeof setTimeout> | null>(null);
  const ref = useRef<HTMLDivElement>(null);

  const dbResults = useMemo(() => {
    if (q.trim().length < 2) return [];
    const query = q.trim().toLowerCase();
    return items.filter(i => `${i.title} ${i.excerpt||""} ${i.source_name}`.toLowerCase().includes(query)).slice(0,6);
  }, [q, items]);

  useEffect(() => {
    const h = (e: MouseEvent) => { if (ref.current && !ref.current.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", h);
    return () => document.removeEventListener("mousedown", h);
  }, []);

  function handleChange(val: string) {
    setQ(val); setOpen(val.trim().length >= 2);
    if (debounce.current) clearTimeout(debounce.current);
    if (val.trim().length >= 3) {
      debounce.current = setTimeout(async () => { setWebLoading(true); setWebResults(await searchDuckDuckGo(val)); setWebLoading(false); }, 700);
    } else { setWebResults([]); }
  }

  const SEV_DOT: Record<string,string> = { critical:"bg-red-500",high:"bg-orange-400",medium:"bg-blue-400",low:"bg-green-500" };
  return (
    <div ref={ref} className="relative mb-5">
      <div className="relative">
        <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground pointer-events-none" />
        <Input value={q} onChange={e => handleChange(e.target.value)} onFocus={() => { if (q.trim().length >= 2) setOpen(true); }}
          placeholder="Live search — threats, CVEs, malware, actors… results appear instantly"
          className="pl-9 h-10 pr-8" />
        {q && <button onClick={() => { setQ(""); setWebResults([]); setOpen(false); }} className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground text-xs">✕</button>}
      </div>
      {open && (dbResults.length > 0 || webResults.length > 0 || webLoading) && (
        <div className="absolute left-0 right-0 top-[calc(100%+4px)] z-50 rounded-xl border border-border/60 bg-card shadow-xl overflow-hidden">
          {dbResults.length > 0 && (
            <div className="border-b border-border/40">
              <div className="px-4 pt-2.5 pb-1 text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Your Feed</div>
              {dbResults.map(item => (
                <a key={item.id} href={item.link} target="_blank" rel="noopener noreferrer"
                  className="flex items-start gap-2.5 px-4 py-2.5 hover:bg-muted/40 transition-colors group">
                  <span className={`mt-1.5 h-1.5 w-1.5 rounded-full shrink-0 ${SEV_DOT[item.severity]||"bg-muted"}`} />
                  <div className="flex-1 min-w-0">
                    <div className="text-xs font-medium line-clamp-1 group-hover:text-primary">{item.title}</div>
                    <div className="text-[10px] text-muted-foreground">{item.source_name} · {timeAgo(itemDisplayDate(item))}</div>
                  </div>
                  <ExternalLink className="h-3 w-3 shrink-0 mt-0.5 text-muted-foreground opacity-0 group-hover:opacity-100" />
                </a>
              ))}
            </div>
          )}
          <div>
            <div className="px-4 pt-2.5 pb-1 text-[10px] font-bold uppercase tracking-widest text-muted-foreground flex items-center gap-2">
              <Globe className="h-3 w-3" /> DuckDuckGo Web {webLoading && <RefreshCw className="h-2.5 w-2.5 animate-spin text-primary" />}
            </div>
            {webLoading && webResults.length === 0 && <div className="px-4 py-2.5 text-xs text-muted-foreground">Searching…</div>}
            {webResults.slice(0,5).map((r, i) => (
              <a key={i} href={r.link} target="_blank" rel="noopener noreferrer"
                className="flex items-start gap-2.5 px-4 py-2.5 hover:bg-muted/40 transition-colors group">
                <Globe className="h-3.5 w-3.5 shrink-0 mt-0.5 text-muted-foreground" />
                <div className="flex-1 min-w-0">
                  <div className="text-xs font-medium line-clamp-1 group-hover:text-primary">{r.title}</div>
                  <div className="text-[10px] text-muted-foreground">{r.source}{r.snippet?` · ${r.snippet.slice(0,60)}`:""}</div>
                </div>
                <ExternalLink className="h-3 w-3 shrink-0 mt-0.5 text-muted-foreground opacity-0 group-hover:opacity-100" />
              </a>
            ))}
            {dbResults.length===0 && webResults.length===0 && !webLoading && <div className="px-4 py-4 text-sm text-muted-foreground text-center">No results for "{q}"</div>}
          </div>
        </div>
      )}
    </div>
  );
}

// ── WatchlistButton — bookmark a threat to saved_threats ────────────────────
function WatchlistButton({ item, size = "sm" }: { item: ThreatItem; size?: "sm" | "xs" }) {
  const { add, remove, isWatched } = useWatchlist();
  const { toast } = useToast();
  const [saved, setSaved] = useState(false);
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    isWatched(item.id).then(v => { setSaved(v); setChecking(false); });
  }, [item.id]);

  const toggle = async (e: React.MouseEvent) => {
    e.stopPropagation();
    if (saved) {
      await remove(item.id);
      setSaved(false);
      toast({ title: "Removed from watchlist" });
    } else {
      const ok = await add({
        id: item.id,
        title: item.title,
        link: item.link,
        severity: item.severity,
        source_name: item.source_name,
        category: item.category ?? "",
        published_at: item.published_at,
      });
      if (ok) { setSaved(true); toast({ title: "Saved to watchlist" }); }
    }
  };

  if (checking) return null;
  const cls = size === "xs"
    ? "h-3.5 w-3.5"
    : "h-4 w-4";
  return (
    <button
      onClick={toggle}
      title={saved ? "Remove from watchlist" : "Save to watchlist"}
      className={`text-muted-foreground hover:text-primary transition-colors ${saved ? "text-primary" : ""}`}
    >
      {saved ? <BookmarkCheck className={cls} /> : <Bookmark className={cls} />}
    </button>
  );
}

