// MAIN DASHBOARD
// ══════════════════════════════════════════════════════════════════════════════
export default function Index() {
  const { toast } = useToast();
  const [items, setItems]         = useState<ThreatItem[]>([]);
  const [sources, setSources]     = useState<ThreatSource[]>([]);
  const [allCategories, setAllCategories] = useState<string[]>([]);
  const [loading, setLoading]     = useState(true);
  const [watchlistStats, setWatchlistStats] = useState({ total: 0, hits: 0 });
  const relevance = useRelevanceFilter();

  useEffect(() => {
    supabase.from("watchlist_iocs").select("verdict").then(({ data }) => {
      if (data) setWatchlistStats({ total: data.length, hits: data.filter((r: any) => r.verdict === "malicious").length });
    });
  }, []);
  const [fetching, setFetching]   = useState(false);
  const [liveStatus, setLiveStatus] = useState<"connecting"|"connected"|"disconnected">("connecting");
  const [failing, setFailing]     = useState<{ name: string; error: string }[]>([]);
  const [lastSync, setLastSync]   = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState("feed");
  const [severityFilter, setSeverityFilter] = useState("all");
  const [categoryFilter, setCategoryFilter] = useState("all");
  const [search, setSearch]       = useState("");
  const [email, setEmail]         = useState("");
  const [subscribing, setSubscribing] = useState(false);
  const [hasMore, setHasMore]     = useState(true);
  const [page, setPage]           = useState(0);
  const [loadingMore, setLoadingMore] = useState(false);
  const PAGE_SIZE = 200;

  // ── Data fetching ─────────────────────────────────────────────────────────
  const loadItems = useCallback(async (pageNum = 0, append = false, _silent = false) => {
    if ((await getFeedBackend()) === "turso") {
      try {
        const offset = pageNum * PAGE_SIZE;
        const { items: rows, total } = await fetchThreatFeedsBulk({
          maxItems: PAGE_SIZE,
          offset,
          sort: "fetched",
        });
        const filtered = sortByPriorityThenRecency(rows.filter(item => shouldShowFeedItem(item as ThreatItem)) as ThreatItem[]);
        setItems(prev => append ? sortByPriorityThenRecency([...prev, ...filtered]) : filtered);
        setHasMore(offset + filtered.length < total);
        const newest = filtered[0]?.fetched_at || filtered[0]?.published_at;
        if (!append && newest) setLastSync(newest);
      } catch (e) {
        return e;
      }
      return null;
    }

    const cols = "id,source_name,category,title,link,excerpt,severity,published_at,fetched_at,iocs,ai_summary,ai_summary_model,ai_summary_generated_at";
    const colsFallback = "id,source_name,category,title,link,excerpt,severity,published_at,fetched_at,iocs";

    const buildQuery = (c: string, from: number, to: number) =>
      applyHiddenSourceFilter(supabase.from("threat_items").select(c))
        .order("fetched_at", { ascending: false, nullsFirst: false })
        .range(from, to);

    const collected: ThreatItem[] = [];
    const maxScans = append ? 1 : 10;
    let lastError: any = null;
    let lastBatchLen = 0;

    for (let scan = 0; scan < maxScans; scan++) {
      const from = (pageNum + scan) * PAGE_SIZE;
      const to = from + PAGE_SIZE - 1;
      let res: any = await buildQuery(cols, from, to);
      if (res.error?.message?.includes("ai_summary") || res.error?.message?.includes("fetched_at")) {
        res = await buildQuery(colsFallback, from, to);
      }
      if (res.error) { lastError = res.error; break; }
      lastBatchLen = res.data?.length || 0;
      const batch = ((res.data || []) as ThreatItem[]).filter(item => shouldShowFeedItem(item));
      collected.push(...batch);
      if (append || collected.length >= PAGE_SIZE || lastBatchLen < PAGE_SIZE) break;
    }

    // Merge npm/supply-chain + breach rows into main feed (same list, priority-sorted)
    if (!append && !lastError) {
      const extra = await supabase
        .from("threat_items")
        .select(cols)
        .or([
          "category.eq.supply-chain", "category.eq.breach",
          "title.ilike.%npm%", "title.ilike.%data breach%",
          "title.ilike.%malicious package%", "title.ilike.%backdoored%",
          "source_name.ilike.%wiz research%", "source_name.ilike.%socket%",
          "source_name.ilike.%snyk%", "source_name.ilike.%bleepingcomputer%",
        ].join(","))
        .order("fetched_at", { ascending: false, nullsFirst: false })
        .limit(100);
      if (!extra.error && extra.data) {
        for (const item of extra.data as ThreatItem[]) {
          if (shouldShowFeedItem(item)) collected.push(item);
        }
      }
    }

    if (!lastError) {
      const seen = new Set<string>();
      const rows = sortByPriorityThenRecency(collected.filter(r => { if (seen.has(r.id)) return false; seen.add(r.id); return true; }));
      setItems(prev => append ? sortByPriorityThenRecency([...prev, ...rows]) : rows);
      setHasMore(lastBatchLen >= PAGE_SIZE);
      const newest = rows[0]?.fetched_at || rows[0]?.published_at;
      if (!append && newest) setLastSync(newest);
    }
    return lastError;
  }, []);

  const refreshFeed = useCallback(() => {
    clearFeedListCache();
    loadItems(0, false, true).catch(() => {});
  }, [loadItems]);
  useBackgroundRefreshListener(refreshFeed);

  const loadHealth = useCallback(async () => {
    const res = await supabase.from("threat_sources").select("name,last_status").eq("enabled",true).like("last_status","err:%").order("weight",{ascending:false}).limit(10);
    if (!res.error && res.data) setFailing(res.data.map(r => ({ name: r.name, error: (r.last_status||"").replace(/^err:/,"") })));
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      const [err, sourcesRes] = await Promise.all([
        loadItems(0, false),
        supabase.from("threat_sources").select("id,name,url,category,weight,enabled,last_fetched_at,last_status").eq("enabled",true).order("weight",{ascending:false}),
      ]);
      if (cancelled) return;
      if (err) toast({ title:"Failed to load feed", description:String(err), variant:"destructive" });
      if (!sourcesRes.error) setSources((sourcesRes.data||[]) as ThreatSource[]);
      setLoading(false);
    })();
    loadHealth();

    (supabase.rpc as any)("get_distinct_categories").then(({ data }: any) => {
      if (data) setAllCategories((data as { category: string }[]).map(r => r.category).filter(Boolean).sort());
    });

    let pollTimer: ReturnType<typeof setInterval> | null = null;
    let channel: ReturnType<typeof supabase.channel> | null = null;

    void getFeedBackend().then((backend) => {
      if (cancelled) return;
      if (backend === "turso") {
        setLiveStatus("connected");
        pollTimer = setInterval(() => { clearFeedListCache(); loadItems(0, false, true).catch(() => {}); }, 60_000);
        return;
      }
      channel = supabase.channel("live_feed")
      .on("postgres_changes",{event:"INSERT",schema:"public",table:"threat_items"},payload => {
        const item = payload.new as ThreatItem;
        if (!shouldShowFeedItem(item)) return;
        setItems(prev => sortByPriorityThenRecency([item, ...prev.filter(i => i.id !== item.id)]).slice(0, PAGE_SIZE));
        setLastSync(new Date().toISOString());
        toast({ title:`${item.severity==="critical"?"🔴 CRITICAL":item.severity==="high"?"🟠 HIGH":"🔵 NEW"} — ${item.source_name}`, description:item.title.slice(0,100), variant:item.severity==="critical"?"destructive":"default" });
      })
      .on("postgres_changes",{event:"UPDATE",schema:"public",table:"threat_items"},payload => {
        const updated = payload.new as ThreatItem;
        setItems(prev => {
          const idx = prev.findIndex(i => i.id === updated.id);
          if (idx === -1) return sortByPriorityThenRecency([updated as ThreatItem, ...prev]).slice(0, PAGE_SIZE);
          const next = prev.slice();
          next[idx] = { ...next[idx], ...updated };
          return sortByPriorityThenRecency(next);
        });
      })
      .subscribe(s => setLiveStatus(s==="SUBSCRIBED"?"connected":s==="CHANNEL_ERROR"?"disconnected":"connecting"));
    });

    const healthTimer = setInterval(loadHealth, 2*60*1000);

    // Frontend auto-heal watchdog (ingest + UI refresh handled globally every 10s)
    let lastHealAt = 0;
    const watchdog = setInterval(async () => {
      const { data } = await supabase.from("threat_sources").select("id").like("last_status","err:%").eq("enabled",true).limit(1);
      if (data?.length && Date.now() - lastHealAt > 25000) {
        lastHealAt = Date.now();
        supabase.functions.invoke("auto-heal-sources", { body: {} }).catch(() => {});
      }
    }, 30_000);

    return () => { cancelled=true; if (channel) supabase.removeChannel(channel); if (pollTimer) clearInterval(pollTimer); clearInterval(healthTimer); clearInterval(watchdog); };
  }, [loadItems, loadHealth, toast]);

  const loadMore = useCallback(async () => {
    if (loadingMore || !hasMore) return;
    setLoadingMore(true);
    const next = page + 1;
    await loadItems(next, true);
    setPage(next);
    setLoadingMore(false);
  }, [page, hasMore, loadingMore, loadItems]);

  async function triggerFetch() {
    setFetching(true);
    try {
      const result = await triggerFeedIngest();
      if (!result.ok) throw new Error(result.detail ?? "Ingest failed");
      clearFeedListCache();
      await loadItems(0, false);
      toast({ title: "Feed refresh started", description: "Pulling live data from sources — items update in ~30s." });
    } catch (e: unknown) {
      toast({ title: "Fetch failed", description: e instanceof Error ? e.message : "Try again", variant: "destructive" });
    }
    setFetching(false);
  }

  async function handleSubscribe(e: React.FormEvent) {
    e.preventDefault(); if (!email) return; setSubscribing(true);
    try {
      const { data, error } = await supabase.functions.invoke("subscribe",{ body:{ email, min_severity:"critical" } });
      if (error||(data as any)?.error) throw new Error((data as any)?.error||error?.message||"Failed");
      toast({ title:"Subscribed", description:"You'll receive instant alerts on critical threats." }); setEmail("");
    } catch (err: any) { toast({ title:"Subscription failed", description:err.message, variant:"destructive" }); }
    setSubscribing(false);
  }

  // ── Filtering + sorting ────────────────────────────────────────────────────
  const categories = allCategories.length > 0 ? allCategories : [...new Set(items.map(i => i.category))].sort();

  const filtered = useMemo(() => {
    const q = search.trim().toLowerCase();
    return sortByPriorityThenRecency(
      items.filter(i => {
        if (severityFilter !== "all" && i.severity !== severityFilter) return false;
        if (categoryFilter !== "all" && i.category !== categoryFilter) return false;
        if (relevance.enabled && !relevance.isRelevant(i)) return false;
        if (q) return `${i.title} ${i.excerpt||""} ${(i.iocs?.cves||[]).join(" ")} ${(i.iocs?.ipv4||[]).join(" ")}`.toLowerCase().includes(q);
        return true;
      }),
    );
  }, [items, search, severityFilter, categoryFilter, relevance.enabled, relevance.isRelevant]);

  const MALWARE_KW = ["malware","trojan","stealer","backdoor","botnet","infostealer","rootkit","worm","c2 ","cobalt strike"];
  const trendingMalware = useMemo(() =>
    filtered.filter(i => i.category==="malware" || MALWARE_KW.some(k => `${i.title} ${i.excerpt||""}`.toLowerCase().includes(k))).slice(0,5),
  [filtered]);

  // ── Render ─────────────────────────────────────────────────────────────────
  return (
    <div className="relative">
      <div className="pointer-events-none absolute inset-x-0 top-0 h-[500px] bg-gradient-glow" />
      <div className="container relative mx-auto px-4 py-6 max-w-screen-xl">

        {/* ── Status bar ─────────────────────────────────────────────────── */}
        <div className="flex items-center justify-between mb-5 gap-3 flex-wrap">
          <div>
            <div className="flex items-center gap-2 mb-0.5">
              <Shield className="h-5 w-5 text-primary" />
              <h1 className="text-lg font-bold tracking-tight">Threat Intelligence</h1>
              <span className={`inline-flex items-center gap-1 text-[10px] px-2 py-0.5 rounded-full border font-medium ${liveStatus==="connected"?"border-green-500/40 text-green-500 bg-green-500/5":liveStatus==="connecting"?"border-orange-400/40 text-orange-400 bg-orange-400/5":"border-red-500/40 text-red-500 bg-red-500/5"}`}>
                {liveStatus==="connected"?<Wifi className="h-2.5 w-2.5" />:<WifiOff className="h-2.5 w-2.5" />}{liveStatus}
              </span>
            </div>
            <div className="text-xs text-muted-foreground flex items-center gap-3">
              <span>{new Date().toLocaleDateString(undefined,{weekday:"long",month:"long",day:"numeric",year:"numeric"})}</span>
              {lastSync && <span className="flex items-center gap-1"><Clock className="h-3 w-3" />Updated {timeAgo(lastSync)}</span>}
            </div>
          </div>
          <div className="flex items-center gap-2">
            <ComplianceBadge />
            <Button variant="outline" size="sm" onClick={triggerFetch} disabled={fetching} className="gap-2 h-8 text-xs">
              {fetching ? <RefreshCw className="h-3.5 w-3.5 animate-spin" /> : <RefreshCw className="h-3.5 w-3.5" />} Refresh
            </Button>
          </div>
        </div>

        {/* ── Notification bar ────────────────────────────────────────────── */}
        <NotificationBar failing={failing} />

        {/* ── Today's grounded AI briefs (Google News + Groq) ─────────────── */}
        {!loading && items.length > 0 && <AITodayBrief items={items} />}

        {/* ── Charts ──────────────────────────────────────────────────────── */}
        {!loading && items.length > 0 && (
          <section className="mb-6 grid gap-4 md:grid-cols-2 lg:grid-cols-4">
            <VolumeArea items={items} />
            <SeverityDonut items={items} />
            <CategoryBar items={items} />
          </section>
        )}

        {/* ── Trending Malware ─────────────────────────────────────────────── */}
        {trendingMalware.length > 0 && !loading && (
          <section className="mb-6">
            <h2 className="text-sm font-bold uppercase tracking-widest mb-3 flex items-center gap-2 text-muted-foreground">
              <Bug className="h-4 w-4 text-orange-400" /> Trending Malware Threats
              <Badge variant="outline" className="text-[10px]">{trendingMalware.length} active today</Badge>
            </h2>
            <div className="flex flex-col gap-2">
              {trendingMalware.map(item => {
                const sev = SEV[item.severity] || SEV.medium;
                return (
                  <a key={item.id} href={item.link} target="_blank" rel="noopener noreferrer"
                    className={`flex items-center gap-3 rounded-lg border border-border/50 bg-card/60 px-4 py-2.5 hover:border-primary/40 hover:bg-card/80 transition-all border-l-4 ${sev.border}`}>
                    <span className={`text-[10px] font-bold px-2 py-0.5 rounded shrink-0 ${sev.badge}`}>{sev.label}</span>
                    <span className="text-sm font-medium flex-1 line-clamp-1">{item.title}</span>
                    <span className="text-[10px] text-muted-foreground shrink-0">{item.source_name}</span>
                    <span className="text-[10px] text-muted-foreground shrink-0">· {timeAgo(itemDisplayDate(item))}</span>
                    <ExternalLink className="h-3.5 w-3.5 text-muted-foreground shrink-0" />
                  </a>
                );
              })}
            </div>
          </section>
        )}

        {/* ── Dashboard live search ───────────────────────────────────────── */}
        <DashboardSearch items={items} />

        {/* ── Main feed tabs ───────────────────────────────────────────────── */}
        <section className="mb-6">
          <Tabs value={activeTab} onValueChange={setActiveTab}>
            <div className="mb-4 flex flex-col gap-3 md:flex-row md:items-center md:justify-between">
              <TabsList className="bg-card/60">
                <TabsTrigger value="feed" className="flex items-center gap-1.5"><Activity className="h-3.5 w-3.5" /> Live Feed</TabsTrigger>
                <TabsTrigger value="critical" className="flex items-center gap-1.5"><AlertOctagon className="h-3.5 w-3.5 text-destructive" /> Critical</TabsTrigger>
                <TabsTrigger value="iocs" className="flex items-center gap-1.5"><BarChart2 className="h-3.5 w-3.5" /> IOC-Rich</TabsTrigger>
              </TabsList>
              <div className="flex flex-col gap-2 md:flex-row">
                <LiveSearchInput
                  value={search}
                  onChange={setSearch}
                  placeholder="Filter threats, CVEs, IPs…"
                  className="md:w-72"
                />
                <Select value={severityFilter} onValueChange={setSeverityFilter}>
                  <SelectTrigger className="md:w-36 h-9"><SelectValue placeholder="Severity" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All severities</SelectItem>
                    {SEV_ORDER.map(s => <SelectItem key={s} value={s}>{s.toUpperCase()}</SelectItem>)}
                  </SelectContent>
                </Select>
                <Select value={categoryFilter} onValueChange={setCategoryFilter}>
                  <SelectTrigger className="md:w-44 h-9"><SelectValue placeholder="Category" /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All categories</SelectItem>
                    {categories.map(c => <SelectItem key={c} value={c}>{labelFor(c)}</SelectItem>)}
                  </SelectContent>
                </Select>
                {/* Relevance filter toggle */}
                <Button
                  size="sm" variant={relevance.enabled ? "default" : "outline"}
                  className="gap-1.5 h-9 text-xs whitespace-nowrap"
                  onClick={() => relevance.setEnabled(e => !e)}
                  title={relevance.hasProfile ? "Filter threats relevant to your org" : "Set org profile in Settings → Org Profile to enable"}
                  style={relevance.enabled ? { background: "linear-gradient(135deg,#06b6d4,#6366f1)", border: "none" } : {}}
                >
                  <Target className="h-3.5 w-3.5" />
                  {relevance.enabled ? "Relevant Only" : "All Threats"}
                </Button>
              </div>
            </div>

            <TabsContent value="feed">
              <FeedList items={filtered} loading={loading} hasMore={hasMore} loadingMore={loadingMore} onLoadMore={loadMore}
                onExportCSV={() => { exportCSV(filtered); toast({ title:"Exported CSV", description:`${filtered.length} items downloaded.` }); }}
                onExportJSON={() => { exportJSON(filtered); toast({ title:"Exported JSON", description:`${filtered.length} items downloaded.` }); }} />
            </TabsContent>
            <TabsContent value="critical">
              <FeedList items={filtered.filter(i => i.severity==="critical")} loading={loading} hasMore={false} loadingMore={false} onLoadMore={() => {}}
                onExportCSV={() => exportCSV(filtered.filter(i => i.severity==="critical"))}
                onExportJSON={() => exportJSON(filtered.filter(i => i.severity==="critical"))} />
            </TabsContent>
            <TabsContent value="iocs">
              <FeedList
                items={filtered.filter(i => (i.iocs?.cves?.length||0)+(i.iocs?.ipv4?.length||0)+(i.iocs?.sha256?.length||0)>0)}
                loading={loading} hasMore={false} loadingMore={false} onLoadMore={() => {}}
                onExportCSV={() => exportCSV(filtered.filter(i => (i.iocs?.cves?.length||0)>0))}
                onExportJSON={() => exportJSON(filtered.filter(i => (i.iocs?.cves?.length||0)>0))} />
            </TabsContent>
          </Tabs>
        </section>

        {/* ── Subscribe ───────────────────────────────────────────────────── */}
        <section className="mb-6">
          <Card className="border-primary/30">
            <CardContent className="flex flex-col items-start gap-4 p-6 md:flex-row md:items-center md:justify-between">
              <div>
                <h3 className="text-base font-semibold">Instant Critical Alerts</h3>
                <p className="text-sm text-muted-foreground">Get an email the moment a critical threat is detected. Max 1 per 5 min.</p>
              </div>
              <form onSubmit={handleSubscribe} className="flex w-full gap-2 md:w-auto">
                <Input type="email" placeholder="you@company.com" className="md:w-64" value={email} onChange={e => setEmail(e.target.value)} required />
                <Button type="submit" disabled={subscribing}>{subscribing?"…":"Subscribe"}</Button>
              </form>
            </CardContent>
          </Card>
        </section>

        {/* ── IOC Quick Links ──────────────────────────────────────────────── */}
        <section className="mb-6">
          <h2 className="text-sm font-bold uppercase tracking-widest mb-3 flex items-center gap-2 text-muted-foreground">
            <Search className="h-4 w-4 text-primary" /> Quick IOC Lookup
          </h2>
          <div className="grid grid-cols-2 gap-3 md:grid-cols-4 lg:grid-cols-6">
            {[
              {name:"VirusTotal",    url:"https://www.virustotal.com/",     desc:"File/URL/IP/domain"},
              {name:"Shodan",        url:"https://www.shodan.io/",           desc:"Internet-wide scan data"},
              {name:"URLScan.io",    url:"https://urlscan.io/",             desc:"Website scanner"},
              {name:"AbuseIPDB",     url:"https://www.abuseipdb.com/",      desc:"IP reputation"},
              {name:"NVD CVE",       url:"https://nvd.nist.gov/vuln/search",desc:"CVE database"},
              {name:"MITRE ATT&CK",  url:"https://attack.mitre.org/",       desc:"TTP framework"},
              {name:"MalwareBazaar", url:"https://bazaar.abuse.ch/",        desc:"Malware samples"},
              {name:"URLhaus",       url:"https://urlhaus.abuse.ch/",       desc:"Malicious URLs"},
              {name:"ThreatFox",     url:"https://threatfox.abuse.ch/",     desc:"IOC feed"},
              {name:"OTX AlienVault",url:"https://otx.alienvault.com/",     desc:"Threat intel sharing"},
              {name:"GreyNoise",     url:"https://viz.greynoise.io/",       desc:"Internet noise"},
              {name:"CISA KEV",      url:"https://www.cisa.gov/known-exploited-vulnerabilities-catalog",desc:"Exploited CVEs"},
              {name:"Censys",        url:"https://search.censys.io/",       desc:"Internet exposure"},
              {name:"IntelligenceX", url:"https://intelx.io/",              desc:"Dark web search"},
              {name:"Have I Been Pwned",url:"https://haveibeenpwned.com/",  desc:"Breach check"},
              {name:"Feodo Tracker", url:"https://feodotracker.abuse.ch/",  desc:"Botnet C2 tracker"},
              {name:"SSL Blacklist",  url:"https://sslbl.abuse.ch/",        desc:"Malicious SSL certs"},
              {name:"Hybrid Analysis",url:"https://www.hybrid-analysis.com/",desc:"Malware sandbox"},
            ].map(link => (
              <a key={link.name} href={link.url} target="_blank" rel="noopener noreferrer"
                className="rounded-lg border border-border/50 bg-card/40 p-3 hover:border-primary/40 hover:bg-card/80 transition-all group">
                <div className="text-sm font-medium group-hover:text-primary transition-colors">{link.name}</div>
                <div className="text-[10px] text-muted-foreground mt-0.5">{link.desc}</div>
              </a>
            ))}
          </div>
        </section>

      </div>
    </div>
  );
}
