import { Tooltip, TooltipContent, TooltipTrigger } from "@/components/ui/tooltip";
import { ShieldCheck, Shield, ShieldAlert, ShieldX, Info } from "lucide-react";

interface Props {
  score: number;           // 0–100
  crossSourceCount?: number;
  sourceCredibility?: number;
  sourceName?: string;
  reasons?: string[];
  size?: "xs" | "sm" | "md";
  showLabel?: boolean;
}

function tier(score: number) {
  if (score >= 85) return { label: "High",   color: "#10b981", bg: "rgba(16,185,129,0.12)", border: "rgba(16,185,129,0.3)",  Icon: ShieldCheck };
  if (score >= 65) return { label: "Medium", color: "#f59e0b", bg: "rgba(245,158,11,0.12)",  border: "rgba(245,158,11,0.3)",  Icon: Shield };
  if (score >= 40) return { label: "Low",    color: "#f97316", bg: "rgba(249,115,22,0.12)",  border: "rgba(249,115,22,0.3)",  Icon: ShieldAlert };
  return               { label: "Untrusted",color: "#ef4444", bg: "rgba(239,68,68,0.12)",   border: "rgba(239,68,68,0.3)",   Icon: ShieldX };
}

export function ConfidenceBadge({
  score,
  crossSourceCount = 1,
  sourceCredibility = 50,
  sourceName,
  reasons = [],
  size = "sm",
  showLabel = false,
}: Props) {
  const t = tier(score);
  const Icon = t.Icon;

  const sizeMap = {
    xs: { text: "9px", px: "6px 5px", icon: 10, gap: 3 },
    sm: { text: "10px", px: "5px 7px", icon: 11, gap: 4 },
    md: { text: "12px", px: "6px 10px", icon: 13, gap: 5 },
  };
  const s = sizeMap[size];

  const badge = (
    <span
      style={{
        display: "inline-flex",
        alignItems: "center",
        gap: s.gap,
        padding: s.px,
        borderRadius: 6,
        background: t.bg,
        border: `1px solid ${t.border}`,
        color: t.color,
        fontSize: s.text,
        fontWeight: 700,
        fontVariantNumeric: "tabular-nums",
        whiteSpace: "nowrap",
        cursor: "help",
      }}
    >
      <Icon size={s.icon} />
      {score}%
      {showLabel && <span style={{ fontWeight: 500, opacity: 0.85 }}>{t.label}</span>}
    </span>
  );

  const tooltipContent = (
    <div className="text-xs space-y-2 max-w-xs">
      <div className="flex items-center gap-2 font-semibold" style={{ color: t.color }}>
        <Icon size={12} />
        Confidence Score: {score}% ({t.label})
      </div>
      <div className="space-y-1 text-slate-300">
        <div className="flex justify-between gap-4">
          <span className="text-slate-500">Source credibility</span>
          <span>{sourceCredibility}/100</span>
        </div>
        <div className="flex justify-between gap-4">
          <span className="text-slate-500">Cross-source sightings</span>
          <span className={crossSourceCount >= 3 ? "text-emerald-400" : ""}>{crossSourceCount} source{crossSourceCount !== 1 ? "s" : ""}</span>
        </div>
        {sourceName && (
          <div className="flex justify-between gap-4">
            <span className="text-slate-500">Primary source</span>
            <span className="truncate max-w-[140px]">{sourceName}</span>
          </div>
        )}
      </div>
      {crossSourceCount >= 3 && (
        <div className="text-emerald-400 text-[10px] bg-emerald-500/10 rounded px-2 py-1 border border-emerald-500/20">
          ✓ Corroborated by {crossSourceCount} independent sources
        </div>
      )}
      {crossSourceCount === 1 && score < 70 && (
        <div className="text-orange-400 text-[10px] bg-orange-500/10 rounded px-2 py-1 border border-orange-500/20">
          ⚠ Single source — verify before acting
        </div>
      )}
      {reasons.length > 0 && (
        <div className="text-[10px] text-slate-500">
          Signals: {reasons.slice(0, 3).join(", ")}
        </div>
      )}
    </div>
  );

  return (
    <Tooltip>
      <TooltipTrigger asChild>
        <span>{badge}</span>
      </TooltipTrigger>
      <TooltipContent
        side="top"
        className="p-3"
        style={{
          background: "rgba(5,10,20,0.97)",
          border: "1px solid rgba(6,182,212,0.15)",
          borderRadius: 10,
        }}
      >
        {tooltipContent}
      </TooltipContent>
    </Tooltip>
  );
}

export function computeConfidence(
  score: number,
  crossSourceCount: number,
  sourceCredibility: number
): number {
  // Weighted composite: base severity (40%) + source cred (35%) + corroboration (25%)
  const base      = Math.min(score, 100) * 0.40;
  const credPart  = sourceCredibility * 0.35;
  const crossPart = Math.min(crossSourceCount * 15, 30) * (25 / 30);  // cap at 30 pts
  return Math.round(Math.min(base + credPart + crossPart, 100));
}
